    if (roadmap.id === "database-administration") sections.push(...dbaDepth);
    let number = roadmap.modules.length;
    let topicNumber = 0;
    roadmap.modules.forEach((item, moduleIndex) => {
      if (!item.id) item.id = roadmap.id + "-module-" + (moduleIndex + 1);
      item.topics.forEach((node) => {
        topicNumber += 1;
        if (!node.id) node.id = roadmap.id + "-topic-" + topicNumber;
      });
    });
    for (const section of sections) {
      number += 1;
      const next = module(section);
      next.id = roadmap.id + "-module-depth-" + number;
      next.topics = next.topics.map((item) => {
        topicNumber += 1;
        item.id = roadmap.id + "-topic-" + topicNumber;
        return item;
      });
      roadmap.modules.push(next);
    }
